import sys, json
# Also recapture baseline by reading from after-cpm since baseline may be corrupt
# Let's just compare the key packages we care about
after = json.load(sys.stdin)
changes = []
# Known baseline versions
baseline = {
    'Api.csproj': {'System.Text.Json': '10.0.1', 'Azure.Identity': '1.13.2'},
    'Worker.csproj': {'Microsoft.Extensions.Hosting': '8.0.1', 'System.Text.Json': '8.0.4', 'OpenTelemetry.Extensions.Hosting': '1.15.0'},
    'Shared.csproj': {'System.Text.Json': '10.0.1', 'Azure.Identity': '1.11.4'},
    'Tests.csproj': {'xunit': '2.9.3', 'System.Text.Json': '10.0.1'},
}
for proj in after.get('projects', []):
    pname = proj['path'].split('/')[-1]
    for fw in proj.get('frameworks', []):
        for p in fw.get('topLevelPackages', []):
            pkg = p['id']
            rv = p.get('resolvedVersion', '')
            bv = baseline.get(pname, {}).get(pkg, '')
            status = 'Unchanged' if bv == rv else f'{bv} -> {rv} (aligned to highest)'
            if bv != rv:
                changes.append((pname, pkg, status))
            print(f'  {pname}: {pkg} = {rv} [{status}]')
print()
if changes:
    print('VERSION CHANGES:')
    for c in changes:
        print(f'  {c[0]}: {c[1]} {c[2]}')
else:
    print('No version changes.')
